create index post_admission_tasks_student_id on erp.post_admission_tasks(org_id, student_id);
create trigger trg_touch before update on erp.post_admission_tasks for each row execute function app.touch_updated_at();
select app.apply_rls(p_schema => 'erp', p_table => 'post_admission_tasks', p_kind => 'product', p_product => 'erp', p_module => 'admissions');
create policy sel_family on erp.post_admission_tasks for select using (org_id = app.current_org_id() and app.user_has_product(org_id, 'erp') and student_id = any(app.my_learner_ids()));
comment on table erp.post_admission_tasks is 'erp product data (generated by scripts/gen-erp.mjs). module: admissions';

create table erp.facility_bookings (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default app.current_org_id() references core.organizations(id) on delete cascade,
  branch_id uuid default erp.my_branch_id(),
  room_id uuid not null,
  date date not null,
  start_time time not null,
  end_time time not null,
  purpose text,
  status text not null default 'booked' check (status in ('booked', 'cancelled')),
  booked_by uuid default app.uid(),
  created_at timestamptz not null default now(),
  created_by uuid default app.uid(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (org_id, id),
  foreign key (org_id, branch_id) references core.branches(org_id, id),
  foreign key (org_id, room_id) references core.rooms(org_id, id) on delete cascade,
  foreign key (org_id, booked_by) references core.org_users(org_id, user_id) on delete set null (booked_by)
);
create index facility_bookings_branch on erp.facility_bookings(org_id, branch_id);
create index facility_bookings_room_id on erp.facility_bookings(org_id, room_id);
create index facility_bookings_booked_by on erp.facility_bookings(org_id, booked_by);
create trigger trg_touch before update on erp.facility_bookings for each row execute function app.touch_updated_at();
select app.apply_rls(p_schema => 'erp', p_table => 'facility_bookings', p_kind => 'product', p_product => 'erp', p_module => 'facilities');
create policy sel_staff_any on erp.facility_bookings for select using (org_id = app.current_org_id() and app.user_has_product(org_id, 'erp') and (branch_id is null or branch_id = any(app.user_branch_ids())) and app.my_member_kind() in ('staff','support'));
create policy sel_own on erp.facility_bookings for select using (org_id = app.current_org_id() and app.user_has_product(org_id, 'erp') and booked_by = app.uid());
create policy ins_own on erp.facility_bookings for insert with check (org_id = app.current_org_id() and app.user_has_product(org_id, 'erp') and (branch_id is null or branch_id = any(app.user_branch_ids())) and booked_by = app.uid() and app.my_member_kind() in ('staff','support'));
comment on table erp.facility_bookings is 'erp product data (generated by scripts/gen-erp.mjs). module: facilities';
